def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if sys.platform == "win32":
        if "python" in cmd[0]:
            # Python interpreter path too long, split it into multiple tokens
            cmd = tuple([cmd[0][i * 5: (i + 1) * 5] for i in range((len(cmd[0]) + 4) // 5)])
        else:
            # Rewrite deep-path shebangs to be compatible with windows
            if cmd[0].startswith("#!"):
                cmd = tuple([cmd[0][0], "python"] + cmd[0].split(" !")[1:])
    return cmd

