def cachedmethod(self, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    Parameters:
        key (func, optional): A function that takes the arguments to a method
            as its input and returns a hashable object that represents the
            arguments. Defaults to using the method's name and the argument's
            id() if the method is an instance method or the function's name if
            it is a class method.
        lock (bool, optional): A boolean indicating whether to use a lock when
            writing to the cache. Defaults to False.

    Returns:
        A wrapped function that can be used to call the original method.
    """

    def decorate(func):
        if not hasattr(func, '__cache__'):
            func.__cache__ = {}
        def wrapper(*args, **kwargs):
            key_args = key(*args, **kwargs)
            if lock:
                with lock:
                    if key_args not in func.__cache__:
                        func.__cache__[key_args] = func(*args, **kwargs)
                    return func.__cache__[key_args]
            else:
                if key_args not in func.__cache__:
                    func.__cache__[key_args] = func(*args, **kwargs)
                return func.__cache__[key_args]
        return wrapper
    return decorate

